CREATE TABLE app_settings (setting_key TEXT PRIMARY KEY, value_json TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE members (id TEXT PRIMARY KEY, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, phone TEXT, points_balance INTEGER NOT NULL DEFAULT 0 CHECK (points_balance >= 0), note TEXT, created_at TEXT NOT NULL, is_active INTEGER NOT NULL DEFAULT 1 CHECK (is_active IN (0, 1)));
CREATE TABLE product_categories (id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE, is_active INTEGER NOT NULL DEFAULT 1 CHECK (is_active IN (0, 1)), created_at TEXT NOT NULL);
CREATE TABLE products (id TEXT PRIMARY KEY, category_id TEXT REFERENCES product_categories(id) ON UPDATE CASCADE ON DELETE SET NULL, name TEXT NOT NULL, sale_price NUMERIC NOT NULL CHECK (sale_price >= 0), cost_price NUMERIC CHECK (cost_price IS NULL OR cost_price >= 0), is_active INTEGER NOT NULL DEFAULT 1 CHECK (is_active IN (0, 1)), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE snooker_tables (id INTEGER PRIMARY KEY, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, relay_channel INTEGER, is_active INTEGER NOT NULL DEFAULT 1 CHECK (is_active IN (0, 1)));
CREATE TABLE rate_plans (id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE, hourly_rate NUMERIC NOT NULL CHECK (hourly_rate >= 0), minimum_charge NUMERIC NOT NULL CHECK (minimum_charge >= 0), rounding_rule TEXT NOT NULL DEFAULT 'NONE', is_active INTEGER NOT NULL DEFAULT 1 CHECK (is_active IN (0, 1)));
CREATE TABLE table_sessions (id TEXT PRIMARY KEY, table_id INTEGER NOT NULL REFERENCES snooker_tables(id), member_id TEXT REFERENCES members(id) ON DELETE SET NULL, rate_plan_id TEXT REFERENCES rate_plans(id) ON DELETE SET NULL, started_at TEXT NOT NULL, ended_at TEXT, status TEXT NOT NULL CHECK (status IN ('OPEN', 'PAUSED', 'CLOSED', 'CANCELLED')), relay_state TEXT CHECK (relay_state IN ('on', 'off')), legacy_source_id TEXT UNIQUE);
CREATE TABLE session_pauses (id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES table_sessions(id) ON DELETE CASCADE, paused_at TEXT NOT NULL, resumed_at TEXT, reason TEXT);
CREATE TABLE session_items (id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES table_sessions(id) ON DELETE CASCADE, product_id TEXT REFERENCES products(id) ON DELETE SET NULL, product_name_snapshot TEXT NOT NULL, unit_price NUMERIC NOT NULL CHECK (unit_price >= 0), quantity INTEGER NOT NULL CHECK (quantity > 0));
CREATE TABLE sales (id TEXT PRIMARY KEY, bill_number TEXT NOT NULL UNIQUE, table_id INTEGER REFERENCES snooker_tables(id) ON DELETE SET NULL, member_id TEXT REFERENCES members(id) ON DELETE SET NULL, table_name_snapshot TEXT NOT NULL, member_name_snapshot TEXT NOT NULL, started_at TEXT, ended_at TEXT NOT NULL, play_duration_seconds INTEGER NOT NULL DEFAULT 0 CHECK (play_duration_seconds >= 0), play_amount NUMERIC NOT NULL DEFAULT 0 CHECK (play_amount >= 0), food_amount NUMERIC NOT NULL DEFAULT 0 CHECK (food_amount >= 0), discount_amount NUMERIC NOT NULL DEFAULT 0 CHECK (discount_amount >= 0), total_amount NUMERIC NOT NULL CHECK (total_amount >= 0), status TEXT NOT NULL CHECK (status IN ('PENDING', 'PAID', 'VOID')), created_at TEXT NOT NULL, legacy_source_id TEXT UNIQUE);
CREATE TABLE sale_items (id TEXT PRIMARY KEY, sale_id TEXT NOT NULL REFERENCES sales(id) ON DELETE CASCADE, product_id TEXT REFERENCES products(id) ON DELETE SET NULL, product_name_snapshot TEXT NOT NULL, unit_price NUMERIC NOT NULL CHECK (unit_price >= 0), quantity INTEGER NOT NULL CHECK (quantity > 0), line_total NUMERIC NOT NULL CHECK (line_total >= 0));
CREATE TABLE payments (id TEXT PRIMARY KEY, sale_id TEXT NOT NULL REFERENCES sales(id) ON DELETE CASCADE, payment_method TEXT NOT NULL, amount NUMERIC NOT NULL CHECK (amount >= 0), status TEXT NOT NULL CHECK (status IN ('PENDING', 'PAID', 'VOID', 'FAILED')), reference TEXT, created_at TEXT NOT NULL, paid_at TEXT, legacy_source_id TEXT UNIQUE);
CREATE TABLE point_transactions (id TEXT PRIMARY KEY, member_id TEXT NOT NULL REFERENCES members(id), sale_id TEXT REFERENCES sales(id) ON DELETE SET NULL, transaction_type TEXT NOT NULL CHECK (transaction_type IN ('EARN', 'REDEEM', 'ADJUST', 'EXPIRE')), points INTEGER NOT NULL, balance_after INTEGER NOT NULL, note TEXT, created_at TEXT NOT NULL);
CREATE TABLE inventory_movements (id TEXT PRIMARY KEY, product_id TEXT NOT NULL REFERENCES products(id), movement_type TEXT NOT NULL CHECK (movement_type IN ('OPENING', 'PURCHASE', 'SALE', 'ADJUSTMENT', 'WASTE', 'RETURN')), quantity_delta NUMERIC NOT NULL, reference_type TEXT, reference_id TEXT, note TEXT, created_at TEXT NOT NULL);
CREATE TABLE reservations (id TEXT PRIMARY KEY, table_id INTEGER NOT NULL REFERENCES snooker_tables(id), member_id TEXT REFERENCES members(id) ON DELETE SET NULL, customer_name TEXT NOT NULL, starts_at TEXT NOT NULL, ends_at TEXT, status TEXT NOT NULL CHECK (status IN ('BOOKED', 'CHECKED_IN', 'CANCELLED', 'NO_SHOW', 'COMPLETED')), created_at TEXT NOT NULL);
CREATE TABLE audit_events (id TEXT PRIMARY KEY, event_type TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id TEXT, payload_json TEXT, created_at TEXT NOT NULL);
CREATE INDEX idx_table_sessions_table_status ON table_sessions(table_id, status);
CREATE INDEX idx_sales_created_at ON sales(created_at);
CREATE INDEX idx_sales_member_id ON sales(member_id);
CREATE INDEX idx_sale_items_sale_id ON sale_items(sale_id);
CREATE INDEX idx_payments_sale_id ON payments(sale_id);
CREATE INDEX idx_inventory_movements_product_created ON inventory_movements(product_id, created_at);
CREATE INDEX idx_reservations_table_starts ON reservations(table_id, starts_at);
